import { useState } from "react";
import { ConfirmButton } from "@/shared/ui/controls/ConfirmButton";
import { Card } from "@/shared/ui/data/Card";
import { Button } from "@/shared/ui/controls/Button";
import { Stack } from "@/shared/ui/layout/Stack";
import { Row } from "@/shared/ui/layout/Row";
import { Box } from "@/shared/ui/layout/Box";
import { Text } from "@/shared/ui/typography/Text";

// Vendored from `@/shared/lib/core/format` (unresolvable in this sandbox) — unchanged.
function fmtBytes(n) {
  if (n <= 0) return "0 B";
  const u = ["B", "KB", "MB", "GB", "TB"];
  const i = Math.min(u.length - 1, Math.floor(Math.log(n) / Math.log(1024)));
  return `${(n / Math.pow(1024, i)).toFixed(i === 0 ? 0 : 1)} ${u[i]}`;
}
function timeAgoMs(ms) {
  if (ms <= 0) return "\u2014";
  const s = Math.floor((Date.now() - ms) / 1000);
  if (!isFinite(s) || s < 0) return "";
  if (s < 60) return `${s}s ago`;
  const m = Math.floor(s / 60); if (m < 60) return `${m}m ago`;
  const h = Math.floor(m / 60); if (h < 24) return `${h}h ago`;
  const d = Math.floor(h / 24); if (d < 30) return `${d}d ago`;
  return `${Math.floor(d / 30)}mo ago`;
}

// Preview-only stand-in for the real `invoke("list_log_files")` backend call — the Tauri backend
// is unresolvable in this sandbox. Same shape (LogFileInfo[]), fixed sample data.
const SAMPLE_FILES = [
  { stream: "app", label: "App log", path: "app.log", sizeBytes: 482_300, mtimeMs: Date.now() - 60_000, exists: true, text: true },
  { stream: "claude", label: "Claude sessions", path: "claude.log", sizeBytes: 1_240_000, mtimeMs: Date.now() - 3_600_000, exists: true, text: true },
  { stream: "perf", label: "Performance samples", path: "perf.log", sizeBytes: 88_400, mtimeMs: Date.now() - 900_000, exists: true, text: false },
  { stream: "mcp", label: "MCP", path: "mcp.log", sizeBytes: 0, mtimeMs: 0, exists: false, text: true },
];

export function LogsInventoryCard({
  selectedStream = null,
  onViewStream = () => {},
  flash = () => {},
}: {
  selectedStream?: string | null;
  onViewStream?: (stream: string) => void;
  flash?: (msg: string) => void;
}) {
  const [files] = useState(SAMPLE_FILES);

  return (
    <Card title="Log streams">
      <Stack gap={0}>
        {files.map((f) => (
          <Row key={f.stream} gap={12} style={{ padding: "10px 0", borderBottom: "1px solid var(--border-soft)" }}>
            <Box style={{ flex: 1, minWidth: 0 }}>
              <Text as="div" size={13} style={{ fontFamily: "var(--sans)", color: "var(--fg)" }}>{f.label}</Text>
              <Text as="div" mono size={10.5} tone="dim" style={{ marginTop: 2 }}>
                {f.exists ? `${fmtBytes(f.sizeBytes)} \u00b7 ${timeAgoMs(f.mtimeMs)}` : "not created yet"}
              </Text>
            </Box>
            {f.text && <Button size="sm" style={selectedStream === f.stream ? { borderColor: "var(--accent)" } : undefined} onClick={() => onViewStream(f.stream)}>View</Button>}
            {f.exists && <Button size="sm" onClick={() => flash(`Exported to ${f.path}`)}>Export</Button>}
            {f.stream === "perf"
              ? <Text as="span" mono size="xs" tone="dim">retention in Performance →</Text>
              : <ConfirmButton size="sm" label="Clear" armedLabel="Confirm" onConfirm={() => flash(`Cleared ${f.stream}`)} />}
          </Row>
        ))}
      </Stack>
    </Card>
  );
}
